alter table public.analysis_jobs add column if not exists attempts integer not null default 0, add column if not exists max_attempts integer not null default 3, add column if not exists available_at timestamptz not null default now(), add column if not exists lease_expires_at timestamptz, add column if not exists worker_id text;
create index if not exists analysis_jobs_claim_idx on public.analysis_jobs(status,available_at,created_at) where status in ('queued','processing');
create or replace function public.claim_analysis_job(p_worker_id text,p_lease_seconds integer default 1200) returns setof public.analysis_jobs language plpgsql security definer set search_path=public as $$ declare claimed public.analysis_jobs; begin update public.analysis_jobs set status='queued',stage='queued',worker_id=null,lease_expires_at=null,updated_at=now() where status='processing' and lease_expires_at is not null and lease_expires_at<now() and attempts<max_attempts; update public.analysis_jobs set status='failed',stage='failed',completed_at=now(),updated_at=now() where status='processing' and lease_expires_at is not null and lease_expires_at<now() and attempts>=max_attempts; select * into claimed from public.analysis_jobs where status='queued' and available_at<=now() and attempts<max_attempts order by created_at for update skip locked limit 1; if not found then return; end if; update public.analysis_jobs set status='processing',stage='claimed',attempts=attempts+1,worker_id=p_worker_id,lease_expires_at=now()+make_interval(secs=>greatest(60,least(p_lease_seconds,3600))),started_at=coalesce(started_at,now()),updated_at=now() where id=claimed.id returning * into claimed; return next claimed; end; $$;
revoke all on function public.claim_analysis_job(text,integer) from public,anon,authenticated; grant execute on function public.claim_analysis_job(text,integer) to service_role;
